-- Daily challenges for 2026-09-29: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-09-29

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('apologizing-well', 'Apologizing Well', 'For anyone who over-apologizes, under-apologizes, or freezes when an apology is due. Each day is one small practice in owning a mistake plainly and repairing it, so apologies get simpler and relationships get steadier.', 'Communication', 365, array['Communication', 'Relationships']::text[], 1, '2026-09-29T17:00:00+00:00'::timestamptz),
  ('keeping-in-touch-from-a-distance', 'Keeping in Touch from a Distance', 'For anyone whose family or old friends live far away. Each day is one small way to stay part of each other''s lives across the miles, so distance does not quietly turn into drifting apart.', 'Connection', 365, array['Family', 'Relationships', 'Loneliness']::text[], 1, '2026-09-29T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('apologizing-well', 'keeping-in-touch-from-a-distance');

